import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.SignatureAlgorithm;
import java.util.Date;

public class JwtUtil {
    private static final String SECRET_KEY = "mySecretKeyForDemoOnly12345678";
    private static final long EXPIRATION_MS = 3600000; // 1 hour

    public String generateToken(String username) {
        var now = new Date();
        var expiryDate = new Date(now.getTime() + EXPIRATION_MS);

        return Jwts.builder()
                .setSubject(username) // payload: who the token is for
                .setIssuedAt(now)
                .setExpiration(expiryDate)
                .signWith(SignatureAlgorithm.HS256, SECRET_KEY) // signature creation
                .compact(); // returns Header.Payload.Signature
    }

    public String extractUsername(String token) {
        return Jwts.parser()
                .setSigningKey(SECRET_KEY) // validates signature here
                .parseClaimsJws(token)
                .getBody()
                .getSubject(); // extracts username from payload
    }
}

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.core.userdetails.UserDetailsService;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

@Component
public class JwtAuthenticationFilter extends OncePerRequestFilter {
    private final JwtUtil jwtUtil;
    private final UserDetailsService userDetailsService;

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain) 
            throws ServletException, java.io.IOException {
        var authHeader = request.getHeader("Authorization");

        if (authHeader != null && authHeader.startsWith("Bearer ")) {
            var token = authHeader.substring(7); // strip "Bearer " prefix
            var username = jwtUtil.extractUsername(token);

            if (username != null && SecurityContextHolder.getContext().getAuthentication() == null) {
                var userDetails = userDetailsService.loadUserByUsername(username);

                if (jwtUtil.isTokenValid(token)) {
                    var authToken = new UsernamePasswordAuthenticationToken(
                            userDetails, null, userDetails.getAuthorities());
                    SecurityContextHolder.getContext().setAuthentication(authToken); // user is now authenticated
                }
            }
        }
        chain.doFilter(request, response); // proceed to controller
    }
}

import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.SignatureAlgorithm;
import io.jsonwebtoken.security.Keys;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;
import java.security.Key;
import java.util.Date;
import java.util.Set;

@Component
public class SecureJwtUtil {
    private final Key secretKey;
    private final long accessTokenExpiry = 900000; // 15 minutes
    private final Set<String> tokenBlacklist = new java.util.concurrent.ConcurrentHashMap<>().newKeySet();

    public SecureJwtUtil(@Value("${jwt.secret}") String secret) {
        this.secretKey = Keys.hmacShaKeyFor(secret.getBytes()); // enforces minimum key length
    }

    public String generateToken(String username) {
        return Jwts.builder()
                .setSubject(username)
                .setIssuedAt(new Date())
                .setExpiration(new Date(System.currentTimeMillis() + accessTokenExpiry)) // short expiry
                .signWith(secretKey, SignatureAlgorithm.HS256) // explicit algorithm enforcement
                .compact();
    }

    public boolean isTokenValid(String token) {
        if (tokenBlacklist.contains(token)) return false; // check revocation list

        var claims = Jwts.parserBuilder()
                .setSigningKey(secretKey) // validates signature with correct key
                .build()
                .parseClaimsJws(token) // throws exception if alg is none or signature invalid
                .getBody();

        return claims.getExpiration().after(new Date());
    }

    public void revokeToken(String token) {
        tokenBlacklist.add(token); // manual revocation for critical cases
    }
}

