import org.springframework.http.ResponseCookie;

@PostMapping("/auth/login")
public ResponseEntity<Void> login(@RequestBody LoginRequest req) {
    var user = authService.authenticate(req.username(), req.password());
    var token = jwtUtil.generateToken(user.getUsername());

    // Browser stores the cookie; JavaScript cannot read it (HttpOnly).
    var cookie = ResponseCookie.from("jwt", token)
            .httpOnly(true)            // blocks document.cookie / XSS theft
            .secure(true)             // HTTPS only
            .sameSite("Strict")       // blocks CSRF cross-site sends
            .path("/")
            .maxAge(900)              // 15 minutes
            .build();
    return ResponseEntity.noContent()
            .header("Set-Cookie", cookie.toString())
            .build();
}
```
The token never touches JavaScript, defeating XSS, while `SameSite=Strict` blocks CSRF.

// Controller handling token refresh
@RestController
@RequestMapping("/auth")
public class AuthController {
    private final TokenService tokenService;
    private final RefreshTokenRepository refreshTokenRepo;

    @PostMapping("/refresh")
    public ResponseEntity<TokenResponse> refreshToken(@RequestBody RefreshRequest request) {
        var oldRefreshToken = refreshTokenRepo.findByToken(request.refreshToken())
            .orElseThrow(() -> new UnauthorizedException("Invalid refresh token"));

        if (oldRefreshToken.isExpired()) {
            refreshTokenRepo.delete(oldRefreshToken); // Clean up expired token
            throw new UnauthorizedException("Refresh token expired");
        }

        var user = oldRefreshToken.getUser();
        var newAccessToken = tokenService.generateAccessToken(user); // 15-min expiry
        var newRefreshToken = tokenService.generateRefreshToken(user); // 7-day expiry

        refreshTokenRepo.delete(oldRefreshToken); // Rotation: invalidate old token
        refreshTokenRepo.save(newRefreshToken);

        return ResponseEntity.ok(new TokenResponse(newAccessToken, newRefreshToken.getToken()));
    }
}

record RefreshRequest(String refreshToken) {}
record TokenResponse(String accessToken, String refreshToken) {}
